          <mask id="water"><rect x="0" y="0" width="100%" height="100%" fill="white"/><use href="#feature_2" data-f="2" fill="black"/><use href="#feature_3" data-f="3" fill="black"/><use href="#feature_4" data-f="4" fill="black"/><use href="#feature_5" data-f="5" fill="white"/><use href="#feature_6" data-f="6" fill="white"/><use href="#feature_7" data-f="7" fill="white"/><use href="#feature_8" data-f="8" fill="black"/><use href="#feature_9" data-f="9" fill="white"/><use href="#feature_10" data-f="10" fill="white"/><use href="#feature_11" data-f="11" fill="black"/><use href="#feature_12" data-f="12" fill="black"/><use href="#feature_13" data-f="13" fill="black"/><use href="#feature_14" data-f="14" fill="black"/><use href="#feature_15" data-f="15" fill="black"/><use href="#feature_16" data-f="16" fill="black"/><use href="#feature_17" data-f="17" fill="black"/><use href="#feature_18" data-f="18" fill="black"/><use href="#feature_19" data-f="19" fill="black"/><use href="#feature_20" data-f="20" fill="black"/></mask>
